	public static bool IsNPCIndexImmuneToProjectileType(int projectileType, int npcIndex)
	{
		return perIDStaticNPCImmunity[projectileType, npcIndex] <= Main.GameUpdateCount;
	}

	public static void ResetNPCSlotData(int npcIndex)
	{
		for (int i = 0; i < ProjectileID.Count; i++)
		{
			perIDStaticNPCImmunity[i, npcIndex] = 0u;
		}
		for (int j = 0; j < 1000; j++)
		{
			Main.projectile[j].localNPCImmunity[npcIndex] = 0;
		}
	}

	public void ResetStaticImmunityMatching(long expectedTime)
	{
		for (int i = 0; i < Main.maxNPCs; i++)
		{
			if (perIDStaticNPCImmunity[immunityIdentity, i] == expectedTime)
			{
				perIDStaticNPCImmunity[immunityIdentity, i] = 0u;
			}
		}
	}

	public static bool TryLookup(ProjectileKey key, out Projectile proj)
	{
		proj = Main.projectile[keyToIndex[key.Spawner, key.Index]];
		if ((int)proj.key == (int)key)
		{
			return true;
		}
		proj = null;
		return false;
	}

	public static void ClearAll()
	{
		Array.Clear(slotGenerations, 0, slotGenerations.Length);
		Array.Clear(keyToIndex, 0, keyToIndex.Length);
		for (int i = 0; i < 1000; i++)
		{
			Main.projectile[i] = new Projectile();
			Main.projectile[i].whoAmI = i;
		}
	}

	internal static void AddGameplaySnapshotComponents()
	{
		StateSnapshot.Gameplay.AddRef("Projectile.slotGenerations", () => slotGenerations, (int[] v) =>
		{
			slotGenerations = v;
		});
		StateSnapshot.Gameplay.AddRef("Projectile.keyToIndex", () => keyToIndex, (int[,] v) =>
		{
			keyToIndex = v;
		});
		StateSnapshot.Gameplay.AddRef("Projectile.perIDStaticNPCImmunity", () => perIDStaticNPCImmunity, (uint[,] v) =>
		{
			perIDStaticNPCImmunity = v;
		});
	}

	public bool TurretShouldPersist()
	{
		switch (type)
		{
		case 663:
		case 665:
		case 667:
		case 677:
		case 678:
		case 679:
		case 688:
		case 689:
		case 690:
		case 691:
		case 692:
		case 693:
			return DD2Event.Ongoing;
		default:
			return false;
		}
	}

	private void TransformType(int typeToChangeInto)
	{
		type = typeToChangeInto;
	}

	public void SetDefaults(int Type)
	{
		//IL_0254: Unknown result type (might be due to invalid IL or missing references)
		//IL_0259: Unknown result type (might be due to invalid IL or missing references)
		//IL_025f: Unknown result type (might be due to invalid IL or missing references)
		//IL_0264: Unknown result type (might be due to invalid IL or missing references)
		ownerHitCheckDistance = 1000f;
		counterweight = false;
		sentry = false;
		arrow = false;
		bobber = false;
		numHits = 0;
		netImportant = false;
		manualDirectionChange = false;
		correctSlopeCollision = Main.projPet[Type];
		decidesManualFallThrough = false;
		shouldFallThrough = false;
		bannerIdToRespondTo = 0;
		stopsDealingDamageAfterPenetrateHits = false;
		localNPCHitCooldown = -2;
		idStaticNPCHitCooldown = -1;
		usesLocalNPCImmunity = false;
		usesIDStaticNPCImmunity = false;
		usesOwnerMeleeHitCD = false;
		appliesImmunityTimeOnSingleHits = false;
		int num = 10;
		if (Type >= 0)
		{
			num = ProjectileID.Sets.TrailCacheLength[Type];
		}
		if (num != oldPos.Length)
		{
			Array.Resize(ref oldPos, num);
			Array.Resize(ref oldRot, num);
			Array.Resize(ref oldSpriteDirection, num);
		}
		for (int i = 0; i < oldPos.Length; i++)
		{
			oldPos[i].X = 0f;
			oldPos[i].Y = 0f;
			oldRot[i] = 0f;
			oldSpriteDirection[i] = 0;
		}
		for (int j = 0; j < maxAI; j++)
		{
			ai[j] = 0f;
			localAI[j] = 0f;
		}
		for (int k = 0; k < 255; k++)
		{
			playerImmune[k] = 0;
		}
		ResetLocalNPCHitImmunity();
		noDropItem = false;
		minion = false;
		minionSlots = 0f;
		soundDelay = 0;
		spriteDirection = 1;
		melee = false;
		ranged = false;
		magic = false;
		ownerHitCheck = false;
		drawLayer = 0;
		usesOwnerLight = false;
		hide = false;
		lavaWet = false;
		wetCount = 0;
		wet = false;
		ignoreWater = false;
		isAPreviewDummy = false;
		isAPreviewDisplayDoll = false;
		hostile = false;
		reflected = false;
		netUpdate = false;
		netUpdate2 = false;
		netSpam = 0;
		Array.Clear(netSyncSkippedForPlayer, 0, netSyncSkippedForPlayer.Length);
		numUpdates = 0;
		extraUpdates = 0;
		restrikeDelay = 0;
		light = 0f;
		penetrate = 1;
		tileCollide = true;
		position = Vector2.Zero;
		velocity = Vector2.Zero;
		aiStyle = 0;
		alpha = 0;
		glowMask = -1;
		type = Type;
		immunityIdentity = type;
