		bool num = Main.netMode == 0 || Owner == Main.myPlayer;
		Invariant.Assert(num, "NewProjectile owner ({0}) != myPlayer ({1}). Will not sync or do damage!", Owner, Main.myPlayer);
		if (!num)
		{
			return 1000;
		}
		Projectile projectile = NewProjectileSetup();
		projectile.SetDefaults(Type);
		projectile.position.X = X - (float)projectile.width * 0.5f;
		projectile.position.Y = Y - (float)projectile.height * 0.5f;
		projectile.owner = Owner;
		projectile.velocity.X = SpeedX;
		projectile.velocity.Y = SpeedY;
		projectile.damage = Damage;
		projectile.knockBack = KnockBack;
		projectile.gfxOffY = 0f;
		projectile.stepSpeed = 1f;
		projectile.wet = Collision.WetCollision(projectile.position, projectile.width, projectile.height);
		if (projectile.ignoreWater)
		{
			projectile.wet = false;
