		{
			Item item = theChest.item[i];
			if (item == null)
			{
				continue;
			}
			if (item.IsAir)
			{
				if (num == -1)
				{
					num = i;
				}
			}
			else if (item.type == 5356 && item.stack < item.maxStack)
			{
				flag = true;
