	public static void GetWhipSettings(Projectile proj, out float timeToFlyOut, out int segments, out float rangeMultiplier)
	{
		timeToFlyOut = Main.player[proj.owner].itemAnimationMax * proj.MaxUpdates;
		if (proj.isAPreviewDisplayDoll)
		{
			timeToFlyOut = 60f;
		}
		if (proj.ai[2] >= 1000f)
		{
			timeToFlyOut = proj.ai[2] - 1000f;
		}
		segments = 20;
		rangeMultiplier = 1f;
		switch (proj.type)
		{
		case 1104:
			segments = 36;
			rangeMultiplier *= 0.75f;
			break;
		case 1028:
			segments = 12;
			rangeMultiplier *= 0.75f;
			break;
		case 841:
			rangeMultiplier *= 0.75f;
			break;
		case 1029:
			rangeMultiplier *= 0.95f;
			break;
		case 1030:
			rangeMultiplier *= 0.85f;
			break;
		case 914:
			rangeMultiplier *= 1f;
			break;
		case 1031:
			rangeMultiplier *= 1.1f;
			break;
		case 952:
			rangeMultiplier *= 0.95f;
			break;
		case 913:
			rangeMultiplier *= 1.4f;
			break;
		case 912:
			rangeMultiplier *= 1.5f;
			break;
		case 847:
			segments = 20;
			rangeMultiplier *= 1.75f;
			break;
		case 1032:
			rangeMultiplier *= 1.8f;
			break;
		case 848:
			segments = 40;
			rangeMultiplier = 1.6f;
			break;
		case 849:
			segments = 30;
			rangeMultiplier = 2.15f;
			break;
		case 1033:
			segments = 45;
			rangeMultiplier = 2f;
			break;
		case 915:
			segments = 40;
			rangeMultiplier = 2.2f;
			break;
		case 1034:
			rangeMultiplier *= 2.2f;
			break;
		case 1035:
			segments = 30;
			rangeMultiplier *= 2.2f;
			if (proj.ai[2] >= 10f)
			{
				timeToFlyOut = 30 * proj.MaxUpdates;
			}
			break;
		}
	}

