	private bool Chester_IsAnyPlayerTrackingThisProjectile()
	{
		for (int i = 0; i < 255; i++)
		{
			Player player = Main.player[i];
			if (player.active && player.piggyBankProjTracker.IsTracking(this))
			{
				return true;
			}
		}
		return false;
	}

