	public bool CanGetPickedUpBySentryBackpack()
	{
		//IL_003a: Unknown result type (might be due to invalid IL or missing references)
		//IL_003f: Unknown result type (might be due to invalid IL or missing references)
		//IL_0043: Unknown result type (might be due to invalid IL or missing references)
		if (!sentry)
		{
			return false;
		}
		if (owner != Main.myPlayer)
		{
			return false;
		}
		Player player = Main.player[owner];
		if (!player.accSentryBackpack || player.accSentryBackpackGrabCooldown > 0)
		{
			return false;
		}
		Rectangle hitbox = Hitbox;
		if (!hitbox.Intersects(player.Hitbox))
		{
			return false;
		}
		return true;
	}

	public void SetAsSelectedSentryBackpackTarget()
	{
		Main.player[owner].accSentryBackpackGrabCooldown = 2;
	}

	public bool TryGetContainerIndex(out int containerIndex)
	{
		containerIndex = -1;
		if (type == 525 || type == 960)
		{
			containerIndex = -2;
			return true;
		}
		if (type == 734)
		{
			containerIndex = -5;
			return true;
		}
		return false;
	}

